// src/html.ts
var HtmlFragment = class {
  constructor(value) {
    this.value = value;
  }
};
var fragment = (value) => new HtmlFragment(value);
function escapeHtml(value) {
  const text = String(value);
  if (typeof Bun !== "undefined" && typeof Bun.escapeHTML === "function")
    return Bun.escapeHTML(text);
  return text.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&":
        return "&amp;";
      case "<":
        return "&lt;";
      case ">":
        return "&gt;";
      case '"':
        return "&quot;";
      default:
        return "&#39;";
    }
  });
}
function html(strings, ...values) {
  let result = strings[0];
  for (let index = 0; index < values.length; index++) {
    const value = values[index];
    result += value instanceof HtmlFragment ? value.value : escapeHtml(value);
    result += strings[index + 1];
  }
  return fragment(result);
}
var renderHtml = (value) => value.value;
function jsonForScript(value) {
  const serialized = JSON.stringify(value);
  if (serialized === void 0) throw new TypeError("Expected JSON data");
  return fragment(serialized.replace(/</g, "\\u003c"));
}
var styleElement = (css) => fragment(`<style>
      ${css.replace(/</g, "\\00003c")}
    </style>`);
export {
  html,
  jsonForScript,
  renderHtml,
  styleElement
};
